-- PREPARED ONLY: A-01..A-08 connected Web/Desktop organization and master-data lifecycle workspace.
-- Not applied. Existing tenant, profile, role, catalog, configuration and open-task originals are read only.
-- Runtime gates still required: PostgreSQL/PostgREST/RLS/grants, two sessions, lock/rollback,
-- legacy/native writers, provider sandboxes, browser/layout and qualified care/design/privacy/legal acceptance.
begin;
create schema if not exists organization_lifecycle_private;
revoke all on schema organization_lifecycle_private from public,anon,authenticated;
create table if not exists organization_lifecycle_private.roots(tenant_id uuid primary key,head_id uuid,updated_at timestamptz not null default clock_timestamp());
create table if not exists organization_lifecycle_private.events(id uuid primary key,tenant_id uuid not null,sequence bigint not null,previous_id uuid,request_id uuid not null,actor_id uuid not null,actor_name text not null,occurred_at timestamptz not null,recorded_at timestamptz not null default clock_timestamp(),kind text not null,command jsonb not null,unique(tenant_id,sequence),unique(tenant_id,request_id));
alter table organization_lifecycle_private.roots enable row level security;alter table organization_lifecycle_private.events enable row level security;
revoke all on all tables in schema organization_lifecycle_private from public,anon,authenticated;
create or replace function organization_lifecycle_private.immutable()returns trigger language plpgsql security definer set search_path='' as $$begin raise exception using errcode='P0P01',message='Organisations- und Stammdatenverlauf bleibt unveränderlich.';end$$;
drop trigger if exists organization_lifecycle_roots_delete on organization_lifecycle_private.roots;create trigger organization_lifecycle_roots_delete before delete on organization_lifecycle_private.roots for each row execute function organization_lifecycle_private.immutable();
drop trigger if exists organization_lifecycle_events_immutable on organization_lifecycle_private.events;create trigger organization_lifecycle_events_immutable before update or delete on organization_lifecycle_private.events for each row execute function organization_lifecycle_private.immutable();

create or replace function organization_lifecycle_private.profile_has(t uuid,a uuid,keys text[])returns boolean language sql stable set search_path='' as $$
select exists(select 1 from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and not exists(select 1 from unnest(keys)k where not case when exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key)then exists(select 1 from public.role_permission_sets z where z.tenant_id=t and z.role_key=r.key and z.permission_key=k)else exists(select 1 from public.role_permissions z where z.role_id=r.id and z.permission_key=k)end))$$;
create or replace function organization_lifecycle_private.kind_right(k text)returns text language sql immutable set search_path='' as $$select case when k in('tenant_profile_draft','tenant_profile_review','location_revision','location_switch_review','role_policy_revision','access_decision','clinical_configuration_draft','configuration_activation_decision','catalog_version_draft','catalog_publication_decision','context_transition','work_overview_snapshot','work_item_navigation_review','correction')then'business.tenant.manage'end$$;
create or replace function organization_lifecycle_private.extra_rights(k text)returns text[] language sql immutable set search_path='' as $$select array[]::text[]$$;
create or replace function organization_lifecycle_private.actor(t uuid,a uuid,k text default null)returns text language plpgsql security definer set search_path='' as $$
declare sid uuid;n text;permission text;required text[]:=array['business.tenant.manage'];begin
 if auth.uid()is null or auth.uid()is distinct from a or public.resolve_current_profile_id()is distinct from a or public.current_tenant_id()is distinct from t or coalesce((auth.jwt()->>'exp')::bigint,0)<=extract(epoch from clock_timestamp())then raise exception using errcode='42501',message='Aktuelles eigenes Konto fehlt.';end if;
 sid:=nullif(auth.jwt()->>'session_id','')::uuid;perform 1 from auth.sessions s where s.id=sid and s.user_id=auth.uid()and(s.not_after is null or s.not_after>clock_timestamp())for share;if not found then raise exception using errcode='42501',message='Aktuelle native Sitzung fehlt.';end if;
 permission:=organization_lifecycle_private.kind_right(k);if k is not null and permission is null then raise exception using errcode='22023',message='Organisations- und Stammdatenvorgang ist unbekannt.';end if;if permission is not null then required:=required||permission||organization_lifecycle_private.extra_rights(k);lock table public.roles,public.role_permissions,public.role_permission_sets in share mode;end if;
 select coalesce(nullif(btrim(p.display_name),''),'Name nicht bestätigt')into n from public.profiles p join public.roles r on r.id=p.role_id where p.id=a and p.tenant_id=t and p.is_active and p.status='active'and(p.auth_user_id is null or p.auth_user_id=auth.uid())for share of p,r;
 if n is null or not organization_lifecycle_private.profile_has(t,a,required)then raise exception using errcode='42501',message='Aktuelles Mandanten-Verwaltungsrecht fehlt.';end if;foreach permission in array required loop if public.has_permission(permission)is not true then raise exception using errcode='42501',message='Nativer Rechtezugang fehlt.';end if;end loop;return n;
end$$;

create or replace function organization_lifecycle_private.sources(t uuid)returns jsonb language sql security definer set search_path='' as $$with s as(
 select'tenant'::text kind,x.id,to_jsonb(x)snapshot from public.tenants x where x.id=t
 union all select'tenant_billing_settings',x.id,to_jsonb(x)from public.tenant_billing_settings x where x.tenant_id=t
 union all select'tenant_branding',x.id,to_jsonb(x)from public.tenant_branding x where x.tenant_id=t
 union all select'profile',x.id,to_jsonb(x)from public.profiles x where x.tenant_id=t
 union all select'tenant_user',x.id,to_jsonb(x)from public.tenant_users x where x.tenant_id=t
 union all select'role',x.id,to_jsonb(x)from public.roles x where exists(select 1 from public.profiles p where p.tenant_id=t and p.role_id=x.id)
 union all select'role_permission',x.id,to_jsonb(x)from public.role_permissions x where exists(select 1 from public.profiles p where p.tenant_id=t and p.role_id=x.role_id)
 union all select'tenant_module_settings',x.tenant_id,to_jsonb(x)||jsonb_build_object('id',x.tenant_id)from public.tenant_module_settings x where x.tenant_id=t
 union all select'tenant_service_catalog',x.id,to_jsonb(x)from public.tenant_service_catalog x where x.tenant_id=t
 union all select'service_catalog',x.id,to_jsonb(x)from public.service_catalogs x where x.tenant_id=t
 union all select'service_catalog_item',x.id,to_jsonb(x)from public.service_catalog_items x where x.tenant_id=t
 union all select'access_audit',x.id,to_jsonb(x)from public.privacy_audit_events x where x.tenant_id=t
 union all select'client_task',x.id,to_jsonb(x)from public.client_tasks x where x.tenant_id=t
 union all select'qm_change_task',x.id,to_jsonb(x)from public.qm_change_tasks x where x.tenant_id=t
 union all select'organization_event',x.id,to_jsonb(x)from organization_lifecycle_private.events x where x.tenant_id=t
)select coalesce(jsonb_agg(jsonb_build_object('kind',kind,'id',id,'snapshot',snapshot)order by kind,id),'[]'::jsonb)from s$$;

create or replace function organization_lifecycle_private.source_rules(k text)returns jsonb language sql immutable set search_path='' as $$select case k
 when'tenant_profile_draft'then'{"tenant":["tenant"],"billing":["tenant_billing_settings"],"branding":["tenant_branding"]}'
 when'tenant_profile_review'then'{"tenant":["tenant"],"draft":["organization_event"]}'
 when'location_revision'then'{"tenant":["tenant"],"manager":["profile"]}'
 when'location_switch_review'then'{"fromLocation":["organization_event"],"toLocation":["organization_event"],"assignment":["tenant_user","profile"]}'
 when'role_policy_revision'then'{"role":["role"],"permission":["role_permission"],"assignment":["tenant_user","profile"]}'
 when'access_decision'then'{"account":["tenant_user"],"profile":["profile"],"audit":["organization_event"]}'
 when'clinical_configuration_draft'then'{"tenant":["tenant"],"catalog":["tenant_service_catalog","service_catalog"],"module":["tenant_module_settings"]}'
 when'configuration_activation_decision'then'{"configuration":["organization_event"],"audit":["organization_event"]}'
 when'catalog_version_draft'then'{"catalog":["tenant_service_catalog","service_catalog"],"service":["tenant_service_catalog","service_catalog_item"]}'
 when'catalog_publication_decision'then'{"catalog":["tenant_service_catalog","service_catalog"],"version":["organization_event"]}'
 when'context_transition'then'{"fromContext":["tenant_user","profile","organization_event"],"toContext":["tenant_user","profile","organization_event"],"draft":["organization_event"]}'
 when'work_overview_snapshot'then'{"task":["client_task","qm_change_task"],"audit":["organization_event"]}'
 when'work_item_navigation_review'then'{"task":["client_task","qm_change_task"],"snapshot":["organization_event"]}'
 when'correction'then'{}'end::jsonb$$;
create or replace function organization_lifecycle_private.field_keys(k text)returns text[] language sql immutable set search_path='' as $$select case k
 when'tenant_profile_draft'then array['profileSha256','changeReason','state']when'tenant_profile_review'then array['decision','reviewSha256','openFields']
 when'location_revision'then array['locationId','locationName','scopeSha256','state']when'location_switch_review'then array['policyVersion','beforeSha256','afterSha256','decision']
 when'role_policy_revision'then array['policySha256','scope','state']when'access_decision'then array['decision','reasonCode','decisionSha256']
 when'clinical_configuration_draft'then array['configurationVersion','configurationSha256','validationSha256','state']when'configuration_activation_decision'then array['decision','decisionSha256','limitations']
 when'catalog_version_draft'then array['versionLabel','validFrom','validUntil','changeReason','catalogSha256']when'catalog_publication_decision'then array['decision','historySha256','decisionSha256']
 when'context_transition'then array['generation','visibleBeforeSha256','visibleAfterSha256','draftDisposition']when'work_overview_snapshot'then array['snapshotSha256','coverageSha256','state']
 when'work_item_navigation_review'then array['route','taskRevision','decision']
 when'correction'then array['targetId','reason','evidenceSha256']end$$;
create or replace function organization_lifecycle_private.enum_values(k text,field text)returns text[] language sql immutable set search_path='' as $$select case
 when k='tenant_profile_draft'and field='state'then array['draft','incomplete','withdrawn']
 when k='tenant_profile_review'and field='decision'then array['pending','accepted_candidate','rejected']
 when k='location_revision'and field='state'then array['draft','active_candidate','inactive_candidate']
 when k='location_switch_review'and field='decision'then array['isolated','blocked','incomplete']
 when k='role_policy_revision'and field='state'then array['draft','active_candidate','withdrawn']
 when k='access_decision'and field='decision'then array['allowed','blocked','expired','revoked']
 when k='clinical_configuration_draft'and field='state'then array['valid_candidate','invalid','incomplete']
 when k='configuration_activation_decision'and field='decision'then array['pending','approved_candidate','rejected']
 when k='catalog_publication_decision'and field='decision'then array['pending','approved_candidate','rejected']
 when k='context_transition'and field='draftDisposition'then array['isolated','restored_same_context','discarded_unsent']
 when k='work_overview_snapshot'and field='state'then array['current','incomplete','stale']
 when k='work_item_navigation_review'and field='decision'then array['open_and_accessible','blocked','stale']
 end$$;

create or replace function organization_lifecycle_private.validate_command(cmd jsonb,src jsonb)returns void language plpgsql set search_path='' as $$declare k text:=cmd->>'kind';p jsonb:=cmd->'payload';rules jsonb:=organization_lifecycle_private.source_rules(k);actual text[];expected text[];entry record;v jsonb;begin
select array_agg(x order by x)into actual from jsonb_object_keys(cmd)x;if jsonb_typeof(cmd)is distinct from'object'or actual is distinct from array['actorId','eventId','expectedHeadId','kind','note','occurredAt','payload','requestId','tenantId','version']::text[]or cmd->>'version'<>'2026-10-16.1'or organization_lifecycle_private.kind_right(k)is null or cmd->>'requestId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'eventId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'tenantId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or cmd->>'actorId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'or(cmd->'expectedHeadId'<>'null'::jsonb and cmd->>'expectedHeadId'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')or cmd->>'occurredAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'or nullif(btrim(cmd->>'note'),'')is null or length(cmd->>'note')>4000 or jsonb_typeof(p)is distinct from'object'or rules is null then raise exception using errcode='22023',message='Organisations- und Stammdatenanfrage ist unvollständig.';end if;
 select array_agg(key order by key)into expected from(select jsonb_object_keys(rules)key union all select unnest(organization_lifecycle_private.field_keys(k)))q;select array_agg(x order by x)into actual from jsonb_object_keys(p)x;if actual is distinct from expected then raise exception using errcode='22023',message='Vorgangsfelder sind unvollständig oder enthalten Fremdfelder.';end if;
 for entry in select key,value from jsonb_each(rules)loop v:=p->entry.key;if jsonb_typeof(v)is distinct from'object'or(select array_agg(x order by x)from jsonb_object_keys(v)x)is distinct from array['id','kind','snapshot']::text[]or not exists(select 1 from jsonb_array_elements(entry.value)x where x#>>'{}'=v->>'kind')or v->>'id'!~'^[0-9a-f-]{36}$'or jsonb_typeof(v->'snapshot')is distinct from'object'or v#>>'{snapshot,id}'is distinct from v->>'id'or not exists(select 1 from jsonb_array_elements(src)x where x=v)then raise exception using errcode='40001',message='Originalquelle ist falsch, geändert oder nicht mehr zugänglich.';end if;end loop;
 if k='location_switch_review'and p#>>'{fromLocation,id}'=p#>>'{toLocation,id}'then raise exception using errcode='23514',message='Ein Standortwechsel benötigt zwei verschiedene Standortfassungen.';end if;
 if k='context_transition'and p#>>'{fromContext,id}'=p#>>'{toContext,id}'then raise exception using errcode='23514',message='Ein Kontextwechsel benötigt verschiedene Ausgangs- und Zieloriginale.';end if;
 for entry in select x key from unnest(organization_lifecycle_private.field_keys(k))x loop if nullif(btrim(p->>entry.key),'')is null then raise exception using errcode='22023',message='Pflichtangabe fehlt.';end if;if organization_lifecycle_private.enum_values(k,entry.key)is not null and not((p->>entry.key)=any(organization_lifecycle_private.enum_values(k,entry.key)))then raise exception using errcode='22023',message='Auswahlwert ist ungültig.';elsif entry.key~'(Sha256)$'and(p->>entry.key)!~'^[0-9a-f]{64}$'then raise exception using errcode='22023',message='Fingerabdruck ist ungültig.';elsif entry.key in('validFrom','validUntil')and(p->>entry.key)!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?(Z|[+-][0-9]{2}:[0-9]{2})$'then raise exception using errcode='22007',message='Zeitpunkt ist ungültig.';elsif entry.key in('targetId','locationId')and(p->>entry.key)!~'^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'then raise exception using errcode='22P02',message='UUID ist ungültig.';end if;end loop;
 if k='catalog_version_draft'and(p->>'validUntil')::timestamptz<=(p->>'validFrom')::timestamptz then raise exception using errcode='22007',message='Kataloggültigkeit ist nicht chronologisch.';end if;
end$$;

create or replace function organization_lifecycle_private.event_json(e organization_lifecycle_private.events)returns jsonb language sql immutable set search_path='' as $$select jsonb_build_object('id',e.id,'sequence',e.sequence,'previousId',e.previous_id,'tenantId',e.tenant_id,'actorId',e.actor_id,'actorName',e.actor_name,'recordedAt',to_char(e.recorded_at at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'command',e.command)$$;
create or replace function organization_lifecycle_private.history(t uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare e organization_lifecycle_private.events%rowtype;head uuid;prev uuid;n bigint:=0;rows jsonb:='[]';begin select r.head_id into head from organization_lifecycle_private.roots r where r.tenant_id=t;for e in select*from organization_lifecycle_private.events z where z.tenant_id=t order by z.sequence loop if e.sequence<>n+1 or e.previous_id is distinct from prev or e.command->>'eventId'is distinct from e.id::text or e.command->>'tenantId'is distinct from t::text or e.command->>'actorId'is distinct from e.actor_id::text or(e.command->>'expectedHeadId')is distinct from prev::text then raise exception using errcode='23514',message='Organisations- und Stammdatenverlauf ist widersprüchlich.';end if;rows:=rows||jsonb_build_array(organization_lifecycle_private.event_json(e));prev:=e.id;n:=n+1;end loop;if head is distinct from prev then raise exception using errcode='23514',message='Organisations- und Stammdatenverlaufskopf ist unvollständig.';end if;return jsonb_build_object('version','2026-10-16.1','tenantId',t,'count',n,'headId',head,'events',rows);end$$;
create or replace function organization_lifecycle_private.read_context(t uuid,a uuid)returns jsonb language plpgsql security definer set search_path='' as $$declare n text;src jsonb;begin n:=organization_lifecycle_private.actor(t,a,null);src:=organization_lifecycle_private.sources(t);return jsonb_build_object('version','2026-10-16.1','tenantId',t,'actorId',a,'loadedAt',to_char(clock_timestamp()at time zone'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'sources',jsonb_build_object('count',jsonb_array_length(src),'rows',src),'history',organization_lifecycle_private.history(t));end$$;
create or replace function organization_lifecycle_private.commit_event(cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare t uuid:=(cmd->>'tenantId')::uuid;a uuid:=(cmd->>'actorId')::uuid;rid uuid:=(cmd->>'requestId')::uuid;eid uuid:=(cmd->>'eventId')::uuid;n text;root organization_lifecycle_private.roots%rowtype;e organization_lifecycle_private.events%rowtype;src jsonb;begin n:=organization_lifecycle_private.actor(t,a,cmd->>'kind');perform pg_advisory_xact_lock(hashtextextended('organization-lifecycle:'||t::text,0));insert into organization_lifecycle_private.roots(tenant_id)values(t)on conflict do nothing;select*into root from organization_lifecycle_private.roots r where r.tenant_id=t for update;select*into e from organization_lifecycle_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is not null then if e.command is distinct from cmd then raise exception using errcode='23505',message='Anfragekennung gehört zu anderem Inhalt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',organization_lifecycle_private.event_json(e));end if;src:=organization_lifecycle_private.sources(t);perform organization_lifecycle_private.validate_command(cmd,src);if(cmd->>'expectedHeadId')is distinct from root.head_id::text then raise exception using errcode='40001',message='Organisations- und Stammdatenverlauf wurde geändert.';end if;if cmd->>'kind'='correction'and not exists(select 1 from organization_lifecycle_private.events x where x.tenant_id=t and x.id=(cmd#>>'{payload,targetId}')::uuid and x.kind<>'correction'and not exists(select 1 from organization_lifecycle_private.events z where z.tenant_id=t and z.kind='correction'and z.command#>>'{payload,targetId}'=x.id::text))then raise exception using errcode='23514',message='Nur ein vorhandenes unberichtigtes Original kann berichtigt werden.';end if;insert into organization_lifecycle_private.events(id,tenant_id,sequence,previous_id,request_id,actor_id,actor_name,occurred_at,kind,command)values(eid,t,coalesce((select max(sequence)+1 from organization_lifecycle_private.events where tenant_id=t),1),root.head_id,rid,a,n,(cmd->>'occurredAt')::timestamptz,cmd->>'kind',cmd)returning*into e;update organization_lifecycle_private.roots set head_id=eid,updated_at=clock_timestamp()where tenant_id=t;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',cmd,'event',organization_lifecycle_private.event_json(e));end$$;
create or replace function organization_lifecycle_private.confirm_event(t uuid,a uuid,rid uuid,cmd jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare e organization_lifecycle_private.events%rowtype;begin perform organization_lifecycle_private.actor(t,a,null);select*into e from organization_lifecycle_private.events z where z.tenant_id=t and z.request_id=rid;if e.id is null or e.command is distinct from cmd or e.actor_id<>a then raise exception using errcode='P0P01',message='Passende native Quittung fehlt.';end if;return jsonb_build_object('version','2026-10-16.1','requestId',rid,'command',e.command,'event',organization_lifecycle_private.event_json(e));end$$;
create or replace function public.web_organization_lifecycle_workspace_context(p_tenant_id uuid,p_actor_id uuid)returns jsonb language sql security invoker set search_path='' as $$select organization_lifecycle_private.read_context(p_tenant_id,p_actor_id)$$;
create or replace function public.web_commit_organization_lifecycle_event(p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select organization_lifecycle_private.commit_event(p_command)$$;
create or replace function public.web_confirm_organization_lifecycle_event(p_tenant_id uuid,p_actor_id uuid,p_request_id uuid,p_command jsonb)returns jsonb language sql security invoker set search_path='' as $$select organization_lifecycle_private.confirm_event(p_tenant_id,p_actor_id,p_request_id,p_command)$$;
revoke all on function public.web_organization_lifecycle_workspace_context(uuid,uuid),public.web_commit_organization_lifecycle_event(jsonb),public.web_confirm_organization_lifecycle_event(uuid,uuid,uuid,jsonb)from public,anon;
grant usage on schema organization_lifecycle_private to authenticated;
grant execute on function organization_lifecycle_private.read_context(uuid,uuid),organization_lifecycle_private.commit_event(jsonb),organization_lifecycle_private.confirm_event(uuid,uuid,uuid,jsonb)to authenticated;
grant execute on function public.web_organization_lifecycle_workspace_context(uuid,uuid),public.web_commit_organization_lifecycle_event(jsonb),public.web_confirm_organization_lifecycle_event(uuid,uuid,uuid,jsonb)to authenticated;
commit;
